export function featureUpdateLabels(language='EN'){const i=Math.max(0,featureUpdateLanguages.indexOf(language));return Object.fromEntries(Object.entries(featureWords).map(([key,row])=>[key,row.split('|')[i]]));}
export function featureUpdateText(feature,key,language='EN'){return feature[key][Math.max(0,featureUpdateLanguages.indexOf(language))]||feature[key][0];}
export function readSeenFeatures(storage){
 const raw=storage.getItem(featureUpdatesKey);if(!raw)return {};
 const data=JSON.parse(raw);
 if(data?.version!==1||!data.seen||typeof data.seen!=='object'||Array.isArray(data.seen)||Object.keys(data.seen).length>200)throw Error('storage');
 for(const [key,value]of Object.entries(data.seen))if(!/^[a-z0-9][a-z0-9_.-]{0,79}$/.test(key)||typeof value!=='string'||value.length>100)throw Error('storage');
 return {...data.seen};
}
export function setFeatureSeen(storage,features,seen=true){
 const next=readSeenFeatures(storage);
 for(const feature of features){if(seen)next[feature.id]=feature.revision;else delete next[feature.id];}
 if(Object.keys(next).length>200)throw Error('storage');
 storage.setItem(featureUpdatesKey,JSON.stringify({version:1,seen:next}));return next;
}
export function unseenFeatureUpdates(seen,features=featureUpdates){return features.filter(feature=>seen[feature.id]!==feature.revision);}


