export function attachStudioNavigation({getLanguage=()=> 'EN',features=featureUpdates,getSeen=()=>({})}={}){
 if(document.getElementById('studio-navigation'))return null;
 const header=document.querySelector('.site-header');if(!header)return null;
 const el=(tag,text='')=>{const n=document.createElement(tag);n.textContent=text;return n;};
 const nav=el('nav');nav.id='studio-navigation';nav.className='studio-navigation';
 const quick=el('button');quick.id='studio-archive-shortcut';quick.type='button';
 const label=el('label'),caption=el('span'),select=el('select');select.id='studio-page-map';label.setAttribute('for',select.id);label.append(caption,select);
 const status=el('span');status.className='studio-navigation-status';status.setAttribute('role','status');nav.append(quick,label,status);header.after(nav);
 const labels=()=>studioNavigationLabels(getLanguage());
 const nearest=(id)=>{const n=document.getElementById(id);return n?.closest?.('section,details')||n;};
 const catalog=()=>document.getElementById('media-catalog')||nearest('catalog-title');
 const standard=[
  {id:'top',sectionId:'studio-top',target:()=>header},
  {id:'home',sectionId:'continue-home'},
  {id:'surprise',sectionId:'surprise-title',target:()=>nearest('surprise-title')},
  {id:'reference',sectionId:'image-import-title',target:()=>nearest('image-import-title')},
  {id:'builder',sectionId:'brief',target:()=>nearest('brief')},
  {id:'result',sectionId:'prompt-output',target:()=>nearest('prompt-output')},
  {id:'workbench',sectionId:'prompt-workbench'},
  {id:'library',sectionId:'library-title',target:()=>nearest('library-title')},
  {id:'coach',sectionId:'coach-title',target:()=>nearest('coach-title')},
  {id:'director',sectionId:'director-title',target:()=>nearest('director-title')},
  {id:'archive',sectionId:'media-catalog',target:catalog},
  {id:'gallery',sectionId:'media-catalog',target:()=>document.getElementById('catalog-gallery-toolbar'),gallery:true},
  {id:'ai',sectionId:'ai-hub-dialog',launcherId:'ai-hub-open'},
  {id:'news',sectionId:'feature-updates'}
 ];
 let entries=[];
 const target=e=>e.target?e.target():document.getElementById(e.sectionId);
 function available(e){const n=target(e);if(!n)return false;for(let a=n;a;a=a.parentElement)if(a.hidden)return false;return true;}
 function options(){
  const listed=new Set(standard.map(e=>e.sectionId));const extra=[];
  for(const f of features)if(!listed.has(f.sectionId)){listed.add(f.sectionId);extra.push({id:'feature:'+f.id,sectionId:f.sectionId,launcherId:f.launcherId,feature:f});}
  return [...standard.slice(0,-1),...extra,standard.at(-1)].filter(available);
 }
 function navigate(id){
  const entry=options().find(e=>e.id===id);if(!entry)return false;
  const n=target(entry);if(!n){status.textContent=labels().missing;return false;}
  if(n.tagName==='DIALOG'&&!n.open){const launch=document.getElementById(entry.launcherId);if(!launch)return false;launch.click();}
  for(let a=n;a;a=a.parentElement)if(a.tagName==='DETAILS')a.open=true;
  if(entry.gallery){const controls=document.getElementById('catalog-gallery-day-controls'),button=document.getElementById('catalog-gallery-toggle');if(controls?.hidden&&!button?.disabled)button?.click();}
  const focus=n.querySelector?.('summary')||n.querySelector?.('h2')||n;
  if(!focus.hasAttribute?.('tabindex'))focus.setAttribute('tabindex','-1');
  focus.focus?.({preventScroll:true});n.style.scrollMarginTop=Math.max(64,(nav.getBoundingClientRect?.().height||64)+12)+'px';
  const reduced=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
  n.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});select.value='';status.textContent='';return true;
 }
 function refresh(){
  const t=labels(),seen=getSeen();nav.setAttribute('aria-label',t.map);caption.textContent=t.map;select.setAttribute('aria-label',t.map);
  const quickLabel=quick.querySelector('[data-navigation-caption]');
  if(quickLabel)quickLabel.textContent=t.archiveQuick;else{const text=el('span',t.archiveQuick);text.dataset.navigationCaption='';quick.append(text);}
  entries=options();quick.disabled=!catalog();const selected=select.value;
  const placeholder=el('option',t.choose);placeholder.value='';select.replaceChildren(placeholder);
  for(const entry of entries){const fresh=features.some(f=>f.sectionId===entry.sectionId&&seen[f.id]!==f.revision),name=entry.feature?featureUpdateText(entry.feature,'title',getLanguage()):t[entry.id];const option=el('option',(fresh?'NEW · ':'')+name);option.value=entry.id;select.append(option);}
  select.value=entries.some(e=>e.id===selected)?selected:'';
 }
 const offset=()=>document.documentElement?.style?.setProperty?.('--studio-nav-offset',Math.max(64,(nav.getBoundingClientRect?.().height||64)+12)+'px');
 if(typeof ResizeObserver==='function')new ResizeObserver(offset).observe(nav);offset();
 quick.addEventListener('click',()=>navigate('archive'));select.addEventListener('change',()=>navigate(select.value));
 select.addEventListener('focus',refresh);select.addEventListener('pointerdown',refresh);
 refresh();return {refresh,navigate,entries:()=>entries.map(e=>e.id)};
}

export function attachFeatureUpdates({getLanguage=()=> 'EN',storage=globalThis.localStorage,features=featureUpdates}={}){
 if(document.getElementById('feature-updates'))return null;
 const host=document.querySelector('.custom-library-toolbar')||document.querySelector('.header-right');if(!host)return null;
 let seen={},problem=false,statusKey='';
 try{seen=readSeenFeatures(storage);}catch{problem=true;statusKey='error';}
 const t=()=>featureUpdateLabels(getLanguage()),name=feature=>featureUpdateText(feature,'title',getLanguage());
 const el=(tag,text='',className='')=>{const node=document.createElement(tag);node.textContent=text;if(className)node.className=className;return node;};
 const root=el('details','','feature-updates');root.id='feature-updates';const summary=el('summary'),content=el('div','','feature-updates-content');root.append(summary,content);host.after(root);
 const status=el('p','','feature-updates-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const shortcut=el('button','','feature-updates-launcher');shortcut.id='feature-updates-launcher';shortcut.type='button';shortcut.addEventListener('click',()=>{root.open=true;root.scrollIntoView({behavior:'smooth',block:'start'});});host.append(shortcut);
 const navigation=attachStudioNavigation({getLanguage,features,getSeen:()=>seen});
 const isNew=feature=>seen[feature.id]!==feature.revision;
 function updateLabels(selected,hide=true){
  try{seen=setFeatureSeen(storage,selected,hide);problem=false;statusKey='saved';}catch{problem=true;statusKey='error';}
  render();
 }
 function open(feature){const section=document.getElementById(feature.sectionId);if(!section){statusKey='missing';status.textContent=t().missing;return;}for(let ancestor=section;ancestor;ancestor=ancestor.parentElement)if(ancestor.tagName==='DETAILS')ancestor.open=true;if(section.tagName==='DIALOG'&&!section.open)document.getElementById(feature.launcherId)?.click();section.scrollIntoView({behavior:'smooth',block:'start'});}
 function decorate(){
  for(const feature of features){
   const section=document.getElementById(feature.sectionId),heading=section?.querySelector('summary')||section?.querySelector('h2'),launcher=document.getElementById(feature.launcherId);
   for(const target of [heading,launcher]){
    if(!target)continue;
    const existing=target.querySelector('[data-new-feature="'+feature.id+'"]');
    if(!isNew(feature)){existing?.remove();continue;}
    if(existing){existing.title=name(feature)+' — '+(existing.tagName==='BUTTON'?t().seen:'NEW');if(existing.tagName==='BUTTON')existing.setAttribute('aria-label',existing.title);continue;}
    const actionable=target===heading&&target.tagName!=='BUTTON',badge=el(actionable?'button':'span',actionable?'NEW ×':'NEW','feature-new-badge');badge.dataset.newFeature=feature.id;badge.title=name(feature)+' — '+(actionable?t().seen:'NEW');
    if(actionable){badge.type='button';badge.setAttribute('aria-label',badge.title);badge.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();updateLabels([feature]);});}
    target.append(badge);
   }
  }
 }
 function render(){
  const count=unseenFeatureUpdates(seen,features).length,label=t().title+(count?' ('+count+')':'');summary.textContent=label;shortcut.textContent=label;content.replaceChildren(el('p',t().intro));
  const list=el('div','','feature-updates-list');content.append(list);
  for(const feature of features){
   const row=el('article','','feature-update-row'),title=el('strong',name(feature));row.append(title,el('p',featureUpdateText(feature,'description',getLanguage())));
   const actions=el('div','','feature-update-actions'),locate=el('button',t().open);locate.type='button';locate.addEventListener('click',()=>open(feature));actions.append(locate);
   if(isNew(feature)){const dismiss=el('button',t().seen);dismiss.type='button';dismiss.dataset.featureDismiss=feature.id;dismiss.addEventListener('click',()=>updateLabels([feature]));actions.append(dismiss);}else actions.append(el('span',t().hidden));
   row.append(actions);list.append(row);
  }
  const actions=el('div','','feature-update-actions'),all=el('button',t().all),restore=el('button',t().restore);all.type=restore.type='button';all.disabled=!count;all.dataset.featureAction='all';restore.dataset.featureAction='restore';all.addEventListener('click',()=>updateLabels(features));restore.addEventListener('click',()=>updateLabels(features,false));actions.append(all,restore);content.append(actions,status);status.textContent=t()[statusKey]||'';navigation?.refresh();decorate();
 }
 document.getElementById('ui-language')?.addEventListener('change',render);
 // Other panels can rebuild their headings when edited or translated.
 const observer=typeof MutationObserver==='function'?new MutationObserver(decorate):null;observer?.observe(document.body,{childList:true,subtree:true});
 globalThis.addEventListener?.('storage',event=>{if(event.key===featureUpdatesKey){try{seen=readSeenFeatures(storage);statusKey='';problem=false;}catch{problem=true;statusKey='error';}render();}});
 render();return {refresh:decorate,translate:render,unseen:()=>unseenFeatureUpdates(seen,features).map(feature=>feature.id),hasStorageProblem:()=>problem};
}
